    ('8c276ff6-32a6-5c86-bcb3-6666ea958a28', 'a97a7ff4-29e1-597a-a5fa-3430e170fdcb', 'Speckled Cups, Set of 4', 'speckled-cups-set-of-4', 'Handleless stoneware cups with a speckled glaze, sized for espresso, tea or a short pour.', 42.00, 25, '/images/products/speckled-cups-set-of-4', 'Speckled stoneware cups stacked on a white surface', ARRAY['Holds 180 ml each', 'Dishwasher and microwave safe', 'Set of four']::TEXT[], 40),
    ('359dcbb7-f917-5ccd-befa-aea165a89652', '54c66f31-3397-5307-95f6-81a54e23fc4a', 'Lounge Armchair, Mustard', 'lounge-armchair-mustard', 'A compact armchair with a high back and mustard wool-blend upholstery, sized for reading corners.', 540.00, 25, '/images/products/lounge-armchair-mustard', 'Mustard armchair in a sunlit living room', ARRAY['Width 74 cm, depth 80 cm, height 88 cm', 'Solid ash legs', 'Spot clean']::TEXT[], 50),
